syntax:
// pass by value: a is a COPY
void f(int a) {
    a = a + 1;      // changes only the copy
}

// pass by reference: a is the SAME box as the caller's variable
void g(int &a) {
    a = a + 1;      // changes the caller's variable
}

int x = 5;
f(x);   // x is still 5
g(x);   // x is now 6

// several results: reference parameters carry them back
void minMax(int a, int b, int &smallest, int &largest);

sample.code:
#include <iostream>
using namespace std;

void swapByValue(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int main() {
    int x = 10, y = 20;
    swapByValue(x, y);
    cout << "x = " << x << ", y = " << y << endl;
    return 0;
}

#include <iostream>
using namespace std;

void swapByRef(int &a, int &b) {
    int t = a;
    a = b;
    b = t;
}

int main() {
    int x = 10, y = 20;
    swapByRef(x, y);
    cout << "x = " << x << ", y = " << y << endl;
    return 0;
}

#include <iostream>
using namespace std;

void minMax(int a, int b, int c, int &mn, int &mx) {
    mn = a;
    mx = a;
    if (b < mn) mn = b;
    if (c < mn) mn = c;
    if (b > mx) mx = b;
    if (c > mx) mx = c;
}

void addBonus(int marks) {
    marks = marks + 5;
}

void addBonusRef(int &marks) {
    marks = marks + 5;
}

int main() {
    int lo, hi;
    minMax(8, 3, 15, lo, hi);
    cout << "lo = " << lo << ", hi = " << hi << endl;
    int m = 60;
    addBonus(m);
    cout << "after addBonus: " << m << endl;
    addBonusRef(m);
    cout << "after addBonusRef: " << m << endl;
    return 0;
}

